import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Helper to fetch colors with fallbacks
  const getColor = (key, fallback) => {
    const specColors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
    return specColors[key] ?? fallback;
  };

  const inkColor = new Color(getColor('ink', '#16161d'));
  const paperColor = new Color(getColor('paper', '#e8ecf2'));
  const accentColor = new Color(getColor('accent', '#ff2a38'));
  const surfaceColor = new Color(getColor('surface', '#0b0b10'));

  // Root group for the node
  const root = new Group();

  // ---------- Backdrop Plane (stage) ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  // vertical gradient from surface (bottom) to paper (top)
  backdropMat.colorNode = mix(
    vec3(surfaceColor),
    vec3(paperColor),
    uv().y
  );
  // Machined‑metal look for the backdrop (flat, non‑reflective)
  backdropMat.roughness = 0.7;
  backdropMat.metalness = 0.0;
  backdropMat.clearcoat = 0.0;

  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Load GLB Mesh ----------
  const meshGroup = new Group();
  root.add(meshGroup);
  // async load, but we return immediately
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    // gltf.scene is a THREE.Group / Object3D
    meshGroup.add(gltf.scene);
  });

  // ---------- Apply Cinematic Primitives ----------
  const primitiveInstances = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const name = prim.name;
    const params = prim.params || {};
    if (ctx.primitives && typeof ctx.primitives[name] === 'function') {
      const instance = ctx.primitives[name](root, params);
      primitiveInstances.push(instance);
    }
  }

  // ---------- Event Handlers ----------
  root.userData.handlers = {};

  // Hover: rise‑in (subtle, 0.15 scene units)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: `+=0.15`,
    duration: 0.7,
    ease: 'power3.out',
    onComplete: () => {
      // settle back with overshoot
      gsap.to(root.position, {
        y: `-=0.15`,
        duration: 0.9,
        ease: 'power4.out',
        overwrite: true,
      });
    },
  });

  root.userData.handlers.hover = () => {
    hoverTimeline.restart();
  };

  // Click: emit navigation/event
  root.userData.handlers.click = () => {
    ctx.emit('hub-collection.select');
  };

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose backdrop resources
    backdropGeom.dispose();
    backdropMat.dispose();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }

    // Kill GSAP timelines
    hoverTimeline.kill();

    // Dispose any loaded GLB resources if needed
    // (Assuming GLTF loader handles disposal on scene removal)
    if (meshGroup) {
      meshGroup.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }
  };

  return root;
}
